sdkExamples.typescript:
import { currencyExchangeClient } from "@pontx/frankfurter";

const result = await currencyExchangeClient.exchangeRates.getLatestRates({
  base: "USD",
  symbols: "JPY,CNY"
});

import { frankfurterV2Client } from "@pontx/frankfurter-v2";

const result = await frankfurterV2Client.common.getRates({
  base: "EUR",
  quotes: "USD"
});

import Dida365Client, { Dida365OAuthClient } from "@pontx/dida365";

const oauth = new Dida365OAuthClient({
  client_id: process.env.DIDA365_CLIENT_ID!,
  client_secret: process.env.DIDA365_CLIENT_SECRET!
});
await oauth.authenticate();
const accessToken = await oauth.getAccessToken();
const projects = await Dida365Client.project.getUserProjects({
  headers: { Authorization: `Bearer ${accessToken}` }
});

import { createMassiveClient } from "@pontx/massive";

const client = createMassiveClient({
  apiKey: process.env.MASSIVE_API_KEY!
});
const result = await client.common.getPreviousClose("AAPL", {});

import { createDropboxSignClient } from "@pontx/dropbox-sign";

const client = createDropboxSignClient({
  apiKey: process.env.DROPBOX_SIGN_API_KEY!
});
const result = await client.signatureRequest.signatureRequestList({
  page: 1,
  page_size: 20
});
